/**
 * The Funnies — The Ninety-Nine (SA-090 / F-136).
 *
 * The flock of Luke 15:4, dryly commentating on being the responsible ones
 * nobody wrote a parable about. Captions live here, written against each
 * drawn panel; the panels themselves are generated by Codex from
 * scripts/imagery/strip-panel-subjects.json and installed to
 * public/images/edition/strip/.
 *
 * THE GENERATOR ONLY SERVES PANELS THAT EXIST ON DISK. Until the bank is
 * installed the section renders nothing (F-098's empty-section contract) —
 * no placeholder, and never the retired fedora panels. Rows land as
 * 'draft': caption + image together are editorial voice and pass the queue.
 */
import fs from 'node:fs'
import path from 'node:path'
import type { EditionItem } from '../kinds'

interface StripEntry {
  panelId: string
  /** Basename in public/images/edition/strip/. */
  file: string
  alt: string
  caption: string
}

