const STRIP_DIR = path.join(process.cwd(), 'public/images/edition/strip')

function dayOfYearUTC(date: Date): number {
  const startOfYear = Date.UTC(date.getUTCFullYear(), 0, 1)
  return (
    Math.floor(
      (Date.UTC(date.getUTCFullYear(), date.getUTCMonth(), date.getUTCDate()) -
        startOfYear) /
        86400000,
    ) + 1
  )
}

export async function generateStrip(
  date: Date,
): Promise<EditionItem<'strip'>[]> {
  // Only panels whose artwork is actually installed. An empty pool is NOT an
  // error — the bank simply is not drawn yet, and the section stays absent.
  const available = STRIP_BANK.filter((e) =>
    fs.existsSync(path.join(STRIP_DIR, e.file)),
  )
  if (available.length === 0) return []

  const entry = available[dayOfYearUTC(date) % available.length]
  return [
    {
      kind: 'strip',
      publishDate: date.toISOString().slice(0, 10),
      slot: 0,
      status: 'draft',
      payload: {
        image: `/images/edition/strip/${entry.file}`,
        alt: entry.alt,
        caption: entry.caption,
        panelId: entry.panelId,
      },
    },
  ]
}
